          Math.Min(sp.lag2_inOpen, sp.lag2_inClose) < sp.lag4_inClose && /* 3rd to 4th hold within 1st: a part of the real body must be within 1st real body */
          Math.Min(sp.lag1_inOpen, sp.lag1_inClose) < sp.lag4_inClose &&
